func (self class) Virtual(name string) reflect.Value {
	switch name {
	default: return gd.VirtualByName(Popup.Advanced(self.AsPopup()), name)
	}
}

func (self Instance) Virtual(name string) reflect.Value {
	switch name {
	default: return gd.VirtualByName(Popup.Instance(self.AsPopup()), name)
	}
}
func init() {gdclass.Register("PopupPanel", func(ptr gdreference.Object) any { return Instance{gdclass.NewPopupPanel(ptr)} })}
